impl Checker<'_> {
    /// Generate a [`Fix`] to remove an unnecessary dictionary spread.
    fn unnecessary_spread_fix(&self, dict: &ast::ExprDict, prev_end: TextSize) -> Option<Fix> {
        let locator = self.locator();
        let contents = locator.contents();
        let index = locator.to_index();

        if usize::from(dict.range.end()) > contents.len() {
            return None;
        }

        let start_line = index.line_index(dict.range.start());
        if dict.range.start() < index.line_start(start_line, contents) {
            return None;
        }

        // Find the `**` token preceding the spread.
        let doublestar = SimpleTokenizer::starts_at(prev_end, contents)
            .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;

        // Determine whether the dict is wrapped in parentheses, e.g., `**({...})`,
        // collecting the parentheses that must be removed alongside the braces.
        let mut parens = 0usize;
        let mut edits = vec![];
        for tok in SimpleTokenizer::starts_at(doublestar.end(), contents) {
            if tok.start() >= dict.range.start() {
                break;
            }
            match tok.kind() {
                SimpleTokenKind::LParen => {
                    parens += 1;
                    edits.push(Edit::range_deletion(tok.range()));
                }
                kind if kind.is_trivia() => {}
                _ => break,
            }
        }

        if let Some(last_item) = dict.items.last() {
            // Ex) `**{a: 1, b: 2}`
            if let Some(key) = last_item.key.as_ref() {
                if key.start() > last_item.value.start() {
                    return None;
                }
            }
            let last_end = last_item.value.end();
            if parens == 0 {
                for tok in SimpleTokenizer::starts_at(last_end, contents).skip_trivia() {
                    match tok.kind() {
                        SimpleTokenKind::Comma => {
                            edits.push(Edit::range_deletion(tok.range()));
                        }
                        SimpleTokenKind::RBrace => {
                            edits.push(Edit::range_deletion(tok.range()));
                            break;
                        }
                        _ => {}
                    }
                }
            } else {
                // Ex) `**({a: 1, b: 2})`
                // Delete any trailing comma of the last item, e.g.,
                // `**({a: 1,})`.
                for tok in SimpleTokenizer::starts_at(last_end, contents).skip_trivia() {
                    match tok.kind() {
                        SimpleTokenKind::Comma => {
                            edits.push(Edit::range_deletion(tok.range()));
                        }
                        SimpleTokenKind::RBrace => break,
                        _ => {}
                    }
                }
                // Delete the opening brace of the dict.
                edits.push(Edit::deletion(
                    dict.range.start(),
                    dict.range.start() + TextSize::from(1),
                ));
                // Delete the closing brace of the dict, as well as the
                // parentheses that wrap it, but leave any trailing comma
                // in place.
                edits.push(Edit::deletion(
                    dict.range.end() - TextSize::from(1),
                    dict.range.end(),
                ));
                let mut removed = 0;
                for tok in SimpleTokenizer::starts_at(dict.range.end(), contents).skip_trivia() {
                    if removed == parens {
                        break;
                    }
                    if let SimpleTokenKind::RParen = tok.kind() {
                        edits.push(Edit::range_deletion(tok.range()));
                        removed += 1;
                    } else {
                        break;
                    }
                }
            }
            Some(Fix::safe_edits(
                // Delete the leading `**` and the opening `{` if unwrapped.
                if parens == 0 {
                    Edit::deletion(doublestar.start(), dict.range.start() + TextSize::from(1))
                } else {
                    Edit::deletion(doublestar.start(), doublestar.end())
                },
                edits,
            ))
        } else if parens == 0 {
            // Ex) `**{}`
            Some(Fix::safe_edit(Edit::deletion(
                doublestar.start(),
                dict.range.end(),
            )))
        } else {
            // Ex) `**({})`
            edits.push(Edit::deletion(dict.range.start(), dict.range.end()));
            let mut removed = 0;
            for tok in SimpleTokenizer::starts_at(dict.range.end(), contents).skip_trivia() {
                if removed == parens {
                    break;
                }
                if let SimpleTokenKind::RParen = tok.kind() {
                    edits.push(Edit::range_deletion(tok.range()));
                    removed += 1;
                } else {
                    break;
                }
            }
            Some(Fix::safe_edits(
                Edit::deletion(doublestar.start(), doublestar.end()),
                edits,
            ))
        }
    }
}
